var t=[{title:`Bescherm de essentie`,text:`Bepaal eerst waar de training vooral voor dient, zoals krachtoefening of aerobe conditie. Besteed een paar minuten aan het opwarmen van de bewegingen die je gaat gebruiken en richt je dan op een of twee hoofdoefeningen. Een korte training heeft nog steeds ruimte nodig voor veilige techniek en genoeg rust bij zware gewichten.`},{title:`Tijdbesparende formaten`,text:`Supersets koppelen oefeningen die niet met elkaar concurreren, zoals rows en squats, en wisselende sets verminderen wachttijd. Circuits kunnen eenvoudige bewegingen aaneenrijgen voor algemene fitheid. Haast je niet tussen zware, technische lifts als vermoeidheid je controle begint te kosten.`},{title:`Voorbeeld`,text:`Warm voor een full-body-training van 15 minuten kort op, wissel twee of drie beheerste sets chair squats en incline push-ups af en sluit af met een row of plank. Pas herhalingen en rust aan op wat je nu kunt. Op een andere dag kan een stevige wandeling of een rustige fietstocht je conditie ondersteunen.`},{title:`Korte momenten tellen op`,text:`Korte momenten van activiteit tellen mee voor je weektotaal. Maak trainingen alleen langer als dat helpt en bij je leven past. Zijn langere blokken niet mogelijk, dan kunnen regelmatige korte trainingen je routine effectief houden.`},{title:`TrainUp gebruiken`,text:`Stel in Profiel je trainingsduur en voorkeursdagen in op de tijd die je echt hebt, en pas ze aan wanneer je planning verandert.`}];var i=[{label:`Praktische richtlijnen van het ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`},{label:`NHS: wandelen voor je gezondheid`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};